                style={{ ...inputSx, fontFamily:'monospace', letterSpacing:2, paddingRight:44,
                  borderColor: kycAadhar && kycAadhar.length===12 ? 'rgba(108,99,255,0.5)' : undefined }}
                placeholder="XXXXXXXXXXXX" maxLength={12} />
