              <div key={k} style={{ marginBottom: 12 }}>
                <label style={labelSx}>{lbl}</label>
                <input type="number" value={limitForm[k]} onChange={e => setLimitForm(f => ({ ...f, [k]: e.target.value }))} style={inputSx} placeholder="0" />
              </div>
