              <textarea value={loanForm.admin_remarks} onChange={e => setLoanForm(f => ({ ...f, admin_remarks: e.target.value }))} style={{ ...inputSx, minHeight:70,resize:'vertical',lineHeight:1.5 }} placeholder="Reason / notes…" />
