                    background: isRevealed ? 'rgba(255,184,76,0.12)' : 'rgba(108,99,255,0.1)',
                    border: `1px solid ${isRevealed ? 'rgba(255,184,76,0.3)' : 'rgba(108,99,255,0.25)'}`,
                    borderRadius: 10, padding: '9px 6px', cursor: 'pointer', fontSize: 12,
                    color: isRevealed ? 'var(--warning)' : 'var(--primary-light)',
                    fontFamily: 'Outfit, sans-serif', fontWeight: 600, transition: 'all 0.2s'
                  }}>
                    {isRevealed ? '🙈 Hide' : '👁️ Reveal'}
                  </button>
                  <button onClick={() => handleFreeze(card.id)} style={{
                    background: card.is_frozen ? 'rgba(0,229,160,0.1)' : 'rgba(108,99,255,0.1)',
                    border: `1px solid ${card.is_frozen ? 'rgba(0,229,160,0.25)' : 'rgba(108,99,255,0.25)'}`,
                    borderRadius: 10, padding: '9px 6px', cursor: 'pointer', fontSize: 12,
                    color: card.is_frozen ? 'var(--success)' : 'var(--primary-light)',
                    fontFamily: 'Outfit, sans-serif', fontWeight: 600, transition: 'all 0.2s'
                  }}>
                    {card.is_frozen ? '🔓 Unfreeze' : '🔒 Freeze'}
                  </button>
                  <button onClick={() => setLimitModal(card)} style={{
                    background: 'rgba(255,255,255,0.05)', border: '1px solid var(--border)',
                    borderRadius: 10, padding: '9px 6px', cursor: 'pointer', fontSize: 12,
                    color: 'var(--text-secondary)', fontFamily: 'Outfit, sans-serif', fontWeight: 600
                  }}>
                    📊 Set Limit
                  </button>
                </div>

                {/* ── Action Buttons row 2 ── */}
                <div className="grid-responsive-2" style={{ gap: 8 }}>
                  <button onClick={() => setBlockConfirm(card)} style={{
                    background: 'rgba(255,184,76,0.06)', border: '1px solid rgba(255,184,76,0.2)',
                    borderRadius: 10, padding: '9px 0', cursor: 'pointer', fontSize: 12,
                    color: 'var(--warning)', fontFamily: 'Outfit, sans-serif', fontWeight: 600
                  }}>
                    🚫 Permanent Block
                  </button>
                  <button onClick={() => setDeleteConfirm(card)} style={{
                    background: 'rgba(255,75,75,0.06)', border: '1px solid rgba(255,75,75,0.2)',
                    borderRadius: 10, padding: '9px 0', cursor: 'pointer', fontSize: 12,
                    color: 'var(--error)', fontFamily: 'Outfit, sans-serif', fontWeight: 600
                  }}>
                    🗑️ Delete Card
                  </button>
                </div>

                {/* Revealed details strip */}
                {isRevealed && (
                  <div style={{ marginTop: 14, background: 'rgba(255,184,76,0.06)', border: '1px solid rgba(255,184,76,0.2)', borderRadius: 12, padding: '12px 16px' }}>
                    <div style={{ fontSize: 11, color: 'var(--warning)', fontWeight: 700, marginBottom: 8 }}>🔓 CARD DETAILS — Keep confidential</div>
                    <div className="grid-responsive-2" style={{ gap: 8 }}>
                      <div>
                        <div style={{ fontSize: 10, color: 'var(--text-muted)', marginBottom: 2 }}>FULL CARD NUMBER</div>
                        <div style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 14, letterSpacing: 2 }}>{revealed.card_number}</div>
                      </div>
                      <div>
                        <div style={{ fontSize: 10, color: 'var(--text-muted)', marginBottom: 2 }}>CVV</div>
                        <div style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 14 }}>•••</div>
                        <div style={{ fontSize: 10, color: 'var(--text-muted)' }}>Check physical card or creation message</div>
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: 10, marginTop: 10 }}>
                      <button onClick={() => copyToClipboard(revealed.card_number.replace(/\s/g, '')).then(() => toast.success('Card number copied!'))}
                        style={{ background: 'rgba(108,99,255,0.12)', border: '1px solid rgba(108,99,255,0.25)', borderRadius: 8, padding: '5px 12px', cursor: 'pointer', fontSize: 11, color: 'var(--primary-light)', fontFamily: 'Outfit, sans-serif', fontWeight: 600 }}>
                        📋 Copy Number
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          );
        })}

        {cards.length === 0 && (
          <div style={{ gridColumn: '1/-1' }}>
            <div className="empty-state">
              <div className="empty-state-icon">💳</div>
              <p>No cards yet. Generate your first virtual card!</p>
              <button className="btn-primary" style={{ marginTop: 16 }} onClick={() => setShowCreate(true)}>+ Generate Card</button>
            </div>
          </div>
        )}
      </div>

      {/* ── Set Limit Modal ── */}
      {limitModal && (
        <div className="modal-overlay" onClick={() => setLimitModal(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h3 style={{ fontWeight: 700, fontSize: 18, marginBottom: 8 }}>📊 Update Daily Spending Limit</h3>
            <p style={{ fontSize: 13, color: 'var(--text-secondary)', marginBottom: 16 }}>
              Card ···{limitModal.card_number_last4} · Current: {formatINR(limitModal.spending_limit)}
            </p>
            <input type="number" className="input-field" placeholder="New limit (₹)" min="1000" max="500000"
              defaultValue={limitModal.spending_limit} id="newLimit" style={{ marginBottom: 20 }} />
            <div style={{ display: 'flex', gap: 10 }}>
              <button className="btn-primary" style={{ flex: 1 }}
                onClick={() => handleUpdateLimit(limitModal.id, document.getElementById('newLimit').value)}>
                ✅ Save Limit
              </button>
              <button className="btn-secondary" style={{ flex: 1 }} onClick={() => setLimitModal(null)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* ── Permanent Block Confirm Modal ── */}
      {blockConfirm && (
        <div className="modal-overlay" onClick={() => setBlockConfirm(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div style={{ textAlign: 'center', marginBottom: 20 }}>
              <div style={{ fontSize: 52, marginBottom: 12 }}>⛔</div>
              <h3 style={{ fontWeight: 800, fontSize: 18, marginBottom: 8 }}>Permanently Block Card?</h3>
              <p style={{ fontSize: 13, color: 'var(--text-secondary)' }}>
                Card <strong>···{blockConfirm.card_number_last4}</strong> will be permanently blocked and <span style={{ color: 'var(--error)' }}>cannot be reactivated</span>. This action is irreversible.
              </p>
            </div>
            <div style={{ background: 'rgba(255,75,75,0.06)', border: '1px solid rgba(255,75,75,0.2)', borderRadius: 10, padding: '12px 14px', marginBottom: 20, fontSize: 12, color: 'var(--error)' }}>
              ⚠️ After blocking, you will need to generate a new card.
            </div>
            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={() => handlePermanentBlock(blockConfirm)} style={{
                flex: 2, padding: '12px 0', background: 'rgba(255,75,75,0.15)', border: '1px solid rgba(255,75,75,0.4)',
                borderRadius: 10, color: 'var(--error)', fontFamily: 'Outfit, sans-serif', fontWeight: 700, cursor: 'pointer', fontSize: 14
              }}>🚫 Yes, Block Permanently</button>
              <button className="btn-secondary" style={{ flex: 1 }} onClick={() => setBlockConfirm(null)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* ── Delete Confirm Modal ── */}
      {deleteConfirm && (
        <div className="modal-overlay" onClick={() => setDeleteConfirm(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div style={{ textAlign: 'center', marginBottom: 20 }}>
              <div style={{ fontSize: 52, marginBottom: 12 }}>🗑️</div>
              <h3 style={{ fontWeight: 800, fontSize: 18, marginBottom: 8 }}>Delete Card?</h3>
              <p style={{ fontSize: 13, color: 'var(--text-secondary)' }}>
                Card <strong>···{deleteConfirm.card_number_last4}</strong> ({deleteConfirm.card_type}) will be permanently deleted from your account.
              </p>
            </div>
            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={() => handleDelete(deleteConfirm)} style={{
                flex: 2, padding: '12px 0', background: 'rgba(255,75,75,0.12)', border: '1px solid rgba(255,75,75,0.3)',
                borderRadius: 10, color: 'var(--error)', fontFamily: 'Outfit, sans-serif', fontWeight: 700, cursor: 'pointer', fontSize: 14
              }}>🗑️ Yes, Delete</button>
              <button className="btn-secondary" style={{ flex: 1 }} onClick={() => setDeleteConfirm(null)}>Cancel</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { accountAPI, transactionAPI } from '../services/api';
import { useAuthStore } from '../store';
import { formatINR, formatDateTime, TXN_STYLES, AVATARS, copyToClipboard } from '../utils/helpers';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import toast from 'react-hot-toast';

const COLORS = ['#6C63FF', '#FF6B9D', '#00E5A0', '#FFB84C', '#5BC8FB', '#FF5757'];

export default function Dashboard() {
  const { user } = useAuthStore();
  const navigate = useNavigate();
  const [summary, setSummary] = useState(null);
  const [accounts, setAccounts] = useState([]);
  const [recentTxns, setRecentTxns] = useState([]);
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [greeting, setGreeting] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [sumRes, accRes, txnRes, anaRes] = await Promise.all([
          accountAPI.getSummary(),
          accountAPI.getAll(),
          transactionAPI.getAll({ limit: 5 }),
          transactionAPI.getAnalytics()
        ]);
        setSummary(sumRes.data.data);
        setAccounts(accRes.data.data);
        setRecentTxns(txnRes.data.data || []);
        setAnalytics(anaRes.data.data);
      } catch (err) {
        toast.error('Failed to load dashboard data');
      } finally {
        setLoading(false);
      }
    };
    fetchData();
    const h = new Date().getHours();
    if (h < 12) setGreeting('Good Morning');
    else if (h < 17) setGreeting('Good Afternoon');
    else setGreeting('Good Evening');
  }, []);

  const avatar = AVATARS[(user?.avatar_id || 1) - 1] || '🦊';

  if (loading) return (
    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '60vh', flexDirection: 'column', gap: 16 }}>
      <div className="spinner" style={{ width: 48, height: 48, borderWidth: 4 }} />
      <p style={{ color: 'var(--text-muted)' }}>Loading your dashboard...</p>
    </div>
  );

  const monthlyChartData = analytics?.monthly?.map(m => ({
    month: m.month?.slice(-2) ? new Date(m.month + '-01').toLocaleString('en-IN', { month: 'short' }) : m.month,
    income: parseFloat(m.income || 0),
    expenses: parseFloat(m.expenses || 0)
  })) || [];

  const categoryData = analytics?.categories?.slice(0, 5) || [];

  return (
    <div style={{ maxWidth: 800, margin: '0 auto', width: '100%' }}>
      {/* Header */}
      <div className="dashboard-header-flex">
        <div>
          <div style={{ fontSize: 14, color: 'var(--text-muted)', marginBottom: 4 }}>{greeting} 👋</div>
          <h1 style={{ fontSize: 28, fontWeight: 800 }}>
            <span style={{ fontSize: 24 }}>{avatar}</span>{' '}
            <span className="text-gradient">{user?.full_name}</span>
          </h1>
          <p style={{ color: 'var(--text-secondary)', fontSize: 13, marginTop: 4 }}>
            {user?.kyc_status === 'verified' ? '✅ KYC Verified' : '⏳ KYC Pending'} · {accounts.length} Account{accounts.length !== 1 ? 's' : ''}
          </p>
        </div>
        <button className="btn-primary hide-on-mobile" onClick={() => navigate('/transfer')} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          💸 Send Money
        </button>
      </div>

      {/* Balance Card */}
      <div className="balance-card" style={{ marginBottom: 24 }}>
        <div style={{ position: 'relative', zIndex: 1 }}>
          <div style={{ fontSize: 14, opacity: 0.8, marginBottom: 8 }}>Total Net Worth</div>
          <div style={{ fontSize: 40, fontWeight: 800, marginBottom: 4, letterSpacing: '-1px' }}>
            {formatINR(summary?.total_balance || 0)}
          </div>
          <div style={{ fontSize: 13, opacity: 0.75 }}>
            Across {summary?.account_count || 0} account{summary?.account_count !== 1 ? 's' : ''}
          </div>
          <div className="balance-stats-flex">
            <div>
              <div style={{ fontSize: 12, opacity: 0.7, marginBottom: 2 }}>↑ This Month Credited</div>
              <div style={{ fontSize: 18, fontWeight: 700 }}>
                {formatINR(summary?.this_month?.total_credits || 0)}
              </div>
            </div>
            <div>
              <div style={{ fontSize: 12, opacity: 0.7, marginBottom: 2 }}>↓ This Month Spent</div>
              <div style={{ fontSize: 18, fontWeight: 700 }}>
                {formatINR(summary?.this_month?.total_debits || 0)}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="dashboard-actions-grid hide-on-mobile">
        {[
          { icon: '💸', label: 'Transfer', path: '/transfer' },
          { icon: '⚡', label: 'UPI Pay', path: '/upi' },
          { icon: '📄', label: 'Pay Bills', path: '/bills' },
          { icon: '💳', label: 'Cards', path: '/cards' },
          { icon: '🏦', label: 'Loans', path: '/loans' },
        ].map(action => (
          <button key={action.label} onClick={() => navigate(action.path)} style={{
            background: 'var(--bg-card)', border: '1px solid var(--border)',
            borderRadius: 14, padding: '16px 8px', cursor: 'pointer',
            display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8,
            transition: 'all 0.2s', color: 'var(--text-primary)', fontFamily: 'Outfit, sans-serif'
          }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(108,99,255,0.1)'; e.currentTarget.style.borderColor = 'rgba(108,99,255,0.3)'; e.currentTarget.style.transform = 'translateY(-2px)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'var(--bg-card)'; e.currentTarget.style.borderColor = 'var(--border)'; e.currentTarget.style.transform = 'none'; }}
          >
            <span style={{ fontSize: 28 }}>{action.icon}</span>
            <span style={{ fontSize: 12, fontWeight: 600, color: 'var(--text-secondary)' }}>{action.label}</span>
          </button>
        ))}
      </div>

      {/* Charts + Accounts row */}
      <div className="dashboard-main-grid">
        {/* Area Chart */}
        <div className="glass-card" style={{ padding: 24 }}>
          <div style={{ marginBottom: 20 }}>
            <div style={{ fontWeight: 700, fontSize: 16 }}>Income vs Expenses</div>
            <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Last 6 months overview</div>
          </div>
          {monthlyChartData.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <AreaChart data={monthlyChartData}>
                <defs>
                  <linearGradient id="income" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#00E5A0" stopOpacity={0.3} />
                    <stop offset="95%" stopColor="#00E5A0" stopOpacity={0} />
                  </linearGradient>
                  <linearGradient id="expenses" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6C63FF" stopOpacity={0.3} />
                    <stop offset="95%" stopColor="#6C63FF" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.05)" />
                <XAxis dataKey="month" stroke="rgba(255,255,255,0.2)" tick={{ fontSize: 12 }} />
                <YAxis stroke="rgba(255,255,255,0.2)" tick={{ fontSize: 12 }} tickFormatter={v => `₹${v >= 1000 ? (v/1000).toFixed(0)+'K' : v}`} />
                <Tooltip
                  contentStyle={{ background: '#1a1a3e', border: '1px solid rgba(108,99,255,0.3)', borderRadius: 8, fontSize: 13 }}
                  formatter={(val) => [formatINR(val)]}
                />
                <Area type="monotone" dataKey="income" stroke="#00E5A0" fill="url(#income)" strokeWidth={2} name="Income" />
                <Area type="monotone" dataKey="expenses" stroke="#6C63FF" fill="url(#expenses)" strokeWidth={2} name="Expenses" />
              </AreaChart>
            </ResponsiveContainer>
          ) : (
            <div className="empty-state"><div className="empty-state-icon">📊</div><p>No chart data yet</p></div>
          )}
        </div>

        {/* Accounts */}
        <div className="glass-card" style={{ padding: 24 }}>
          <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 16 }}>My Accounts</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
            {accounts.map(acc => (
              <div key={acc.id} style={{
                background: 'linear-gradient(135deg, rgba(108,99,255,0.08) 0%, rgba(255,107,157,0.05) 100%)',
                borderRadius: 14, padding: '16px',
                border: '1px solid rgba(108,99,255,0.2)',
                position: 'relative', overflow: 'hidden'
              }}>
                {/* Account type + status */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                  <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--primary-light)', textTransform: 'uppercase', letterSpacing: 1 }}>
                    🏦 {acc.account_type} Account
                  </span>
                  <span className={`badge ${acc.status === 'active' ? 'badge-success' : 'badge-error'}`}>{acc.status}</span>
                </div>

                {/* Balance */}
                <div style={{ fontSize: 22, fontWeight: 800, marginBottom: 12, letterSpacing: '-0.5px' }}>
                  {formatINR(acc.balance)}
                </div>

                {/* Account Number with copy */}
                <div style={{ marginBottom: 8 }}>
                  <div style={{ fontSize: 11, color: 'var(--text-muted)', fontWeight: 600, marginBottom: 3, textTransform: 'uppercase', letterSpacing: 0.8 }}>
                    Account Number
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
                    <span style={{ fontSize: 14, fontFamily: 'monospace', fontWeight: 700, color: 'var(--text-primary)', letterSpacing: 1.5 }}>
                      {acc.account_number.replace(/(\d{4})/g, '$1 ').trim()}
                    </span>
                    <button
                      onClick={() => copyToClipboard(acc.account_number).then(() => toast.success('Account number copied!'))}
                      title="Copy account number"
                      style={{
                        background: 'rgba(108,99,255,0.12)', border: '1px solid rgba(108,99,255,0.25)',
                        borderRadius: 6, padding: '4px 10px', cursor: 'pointer', fontSize: 12,
                        color: 'var(--primary-light)', fontFamily: 'Outfit, sans-serif', fontWeight: 600,
                        transition: 'all 0.18s', whiteSpace: 'nowrap'
                      }}
                      onMouseEnter={e => e.currentTarget.style.background = 'rgba(108,99,255,0.25)'}
                      onMouseLeave={e => e.currentTarget.style.background = 'rgba(108,99,255,0.12)'}
                    >
                      📋 Copy
                    </button>
                  </div>
                </div>

                {/* IFSC Code with copy */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
                  <div>
                    <div style={{ fontSize: 11, color: 'var(--text-muted)', fontWeight: 600, marginBottom: 2, textTransform: 'uppercase', letterSpacing: 0.8 }}>
                      IFSC Code
                    </div>
                    <span style={{ fontSize: 14, fontFamily: 'monospace', fontWeight: 700, color: 'var(--success)', letterSpacing: 1 }}>
                      {acc.ifsc_code}
                    </span>
                  </div>
                  <button
                    onClick={() => copyToClipboard(acc.ifsc_code).then(() => toast.success('IFSC code copied!'))}
                    title="Copy IFSC code"
                    style={{
                      background: 'rgba(0,229,160,0.08)', border: '1px solid rgba(0,229,160,0.2)',
                      borderRadius: 6, padding: '4px 10px', cursor: 'pointer', fontSize: 12,
                      color: 'var(--success)', fontFamily: 'Outfit, sans-serif', fontWeight: 600,
                      transition: 'all 0.18s', whiteSpace: 'nowrap'
                    }}
                    onMouseEnter={e => e.currentTarget.style.background = 'rgba(0,229,160,0.18)'}
                    onMouseLeave={e => e.currentTarget.style.background = 'rgba(0,229,160,0.08)'}
                  >
                    📋 Copy
                  </button>
                </div>

                {acc.primary_upi && (
                  <div style={{ fontSize: 12, color: 'var(--primary-light)', marginTop: 10, paddingTop: 10, borderTop: '1px solid rgba(255,255,255,0.06)' }}>
                    ⚡ UPI: {acc.primary_upi}
                  </div>
                )}
              </div>
            ))}
            {accounts.length === 0 && <div className="empty-state" style={{ padding: 20 }}>No accounts yet</div>}
          </div>
        </div>
      </div>

      {/* Recent Transactions + Category Pie */}
      <div className="dashboard-main-grid">
        {/* Recent Txns */}
        <div className="glass-card hide-on-mobile" style={{ padding: 24 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
            <div>
              <div style={{ fontWeight: 700, fontSize: 16 }}>Recent Transactions</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Your latest activity</div>
            </div>
            <button className="btn-secondary" onClick={() => navigate('/transactions')} style={{ fontSize: 12, padding: '8px 14px' }}>View All →</button>
          </div>
          {recentTxns.length === 0 ? (
            <div className="empty-state"><div className="empty-state-icon">💸</div><p>No transactions yet</p></div>
          ) : recentTxns.map(txn => {
            const style = TXN_STYLES[txn.type] || TXN_STYLES.debit;
            const isCredit = ['credit', 'upi_receive', 'loan_credit', 'refund'].includes(txn.type);
            return (
              <div key={txn.id} className="txn-item">
                <div className="txn-icon" style={{ background: style.bg, color: style.color, fontSize: 18 }}>{style.icon}</div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 14, fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                    {txn.description || style.label}
                  </div>
                  <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{formatDateTime(txn.created_at)}</div>
                </div>
                <div style={{ textAlign: 'right', flexShrink: 0 }}>
                  <div style={{ fontSize: 15, fontWeight: 700, color: isCredit ? 'var(--success)' : 'var(--error)' }}>
                    {isCredit ? '+' : '-'}{formatINR(txn.amount)}
                  </div>
                  {txn.fraud_flagged && <div style={{ fontSize: 10, color: 'var(--warning)' }}>⚠️ Flagged</div>}
                </div>
              </div>
            );
          })}
        </div>

        {/* Spending by Category */}
        <div className="glass-card" style={{ padding: 24 }}>
          <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 4 }}>Spending This Month</div>
          <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 20 }}>By category</div>
          {categoryData.length > 0 ? (
            <>
              <PieChart width={230} height={160}>
                <Pie data={categoryData} dataKey="total" nameKey="category" cx="50%" cy="50%" outerRadius={70} strokeWidth={2} stroke="rgba(0,0,0,0.3)">
                  {categoryData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                </Pie>
                <Tooltip contentStyle={{ background: '#1a1a3e', border: '1px solid rgba(108,99,255,0.3)', borderRadius: 8, fontSize: 12 }} formatter={v => formatINR(v)} />
              </PieChart>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginTop: 12 }}>
                {categoryData.map((c, i) => (
                  <div key={c.category} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                      <div style={{ width: 8, height: 8, borderRadius: 2, background: COLORS[i % COLORS.length] }} />
                      <span style={{ fontSize: 12, textTransform: 'capitalize', color: 'var(--text-secondary)' }}>{c.category}</span>
                    </div>
                    <span style={{ fontSize: 12, fontWeight: 600 }}>{formatINR(c.total)}</span>
                  </div>
                ))}
              </div>
            </>
          ) : (
            <div className="empty-state" style={{ padding: 20 }}>
              <div className="empty-state-icon">🥧</div>
              <p style={{ fontSize: 13 }}>No spending data this month</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useState, useRef } from 'react';
import { supportAPI } from '../services/api';
import { useAuthStore } from '../store';
import toast from 'react-hot-toast';

// ── Tiny helpers ────────────────────────────────────────────────────────────────
const fmtDate = (d) => d ? new Date(d).toLocaleString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';

const STATUS_CFG = {
  open:        { color: '#6C63FF', bg: 'rgba(108,99,255,0.15)', label: '🟣 Open' },
  in_progress: { color: '#FFB84C', bg: 'rgba(255,184,76,0.15)', label: '🟡 In Progress' },
  resolved:    { color: '#00E5A0', bg: 'rgba(0,229,160,0.15)',  label: '🟢 Resolved' },
  closed:      { color: '#888',    bg: 'rgba(136,136,136,0.15)',label: '⚫ Closed' },
};
const PRIORITY_CFG = {
  low:    { color: '#888',    label: 'Low' },
  medium: { color: '#6C63FF', label: 'Medium' },
  high:   { color: '#FFB84C', label: '⚡ High' },
  urgent: { color: '#FF5757', label: '🚨 Urgent' },
};
const CATEGORY_LABELS = {
  account:'💳 Account', payment:'💸 Payment', kyc:'📋 KYC',
  card:'💳 Card', loan:'🏦 Loan', upi:'⚡ UPI', other:'❓ Other',
};

const FAQ_ITEMS = [
  { q: 'How do I reset my UPI PIN?', a: 'Go to UPI Pay → Your UPI ID → Settings → Reset PIN. You will need to enter your registered mobile OTP.' },
  { q: 'Why was my transaction declined?', a: 'Transactions can fail due to insufficient balance, incorrect details, or bank server issues. Check your balance and try again. If the issue persists, create a support ticket.' },
  { q: 'How long does KYC verification take?', a: 'KYC verification typically takes 1–3 business days. You will receive a notification when your KYC status is updated.' },
  { q: 'How do I freeze or block my card?', a: 'Go to Cards → Select your card → Toggle Freeze. For permanent block, use the Block Card option. Frozen cards can be unfrozen anytime.' },
  { q: 'How do I add a beneficiary for transfers?', a: 'Go to Transfer → Manage Beneficiaries → Add New. Enter the account number and IFSC code. Beneficiaries are stored for quick future transfers.' },
  { q: 'What is the daily transaction limit?', a: 'Default limits: UPI ₹1,00,000/day, NEFT ₹10,00,000/day, IMPS ₹5,00,000/day. Contact support to request limit increases based on your KYC status.' },
];

// ── Status Badge ────────────────────────────────────────────────────────────────
function StatusBadge({ status }) {
  const cfg = STATUS_CFG[status] || STATUS_CFG.open;
  return (
    <span style={{ background: cfg.bg, color: cfg.color, borderRadius: 8, padding: '3px 10px', fontSize: 11, fontWeight: 700, whiteSpace: 'nowrap' }}>
      {cfg.label}
    </span>
  );
}

// ── Priority Dot ────────────────────────────────────────────────────────────────
function PriorityBadge({ priority }) {
  const cfg = PRIORITY_CFG[priority] || PRIORITY_CFG.medium;
  return <span style={{ color: cfg.color, fontSize: 12, fontWeight: 700 }}>{cfg.label}</span>;
}

// ── FAQ Accordion Item ──────────────────────────────────────────────────────────
function FAQItem({ q, a }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{
      border: `1px solid ${open ? 'rgba(108,99,255,0.4)' : 'var(--border)'}`,
      borderRadius: 12, overflow: 'hidden', transition: 'all 0.25s',
      background: open ? 'rgba(108,99,255,0.04)' : 'transparent', marginBottom: 8
    }}>
      <button onClick={() => setOpen(v => !v)} style={{
        width: '100%', background: 'none', border: 'none', cursor: 'pointer',
        display: 'flex', justifyContent: 'space-between', alignItems: 'center',
        padding: '14px 18px', color: 'var(--text-primary)', fontFamily: 'Outfit, sans-serif',
        fontWeight: 600, fontSize: 14, textAlign: 'left', gap: 12,
      }}>
        <span>{q}</span>
        <span style={{ fontSize: 18, color: 'var(--primary)', transition: 'transform 0.25s', transform: open ? 'rotate(45deg)' : 'none', flexShrink: 0 }}>+</span>
      </button>
      {open && (
        <div style={{ padding: '0 18px 16px', fontSize: 13, color: 'var(--text-secondary)', lineHeight: 1.7 }}>{a}</div>
      )}
    </div>
  );
}

// ── Conversation Message Bubble ─────────────────────────────────────────────────
function MsgBubble({ msg }) {
  const isAdmin = msg.sender_role === 'admin';
  return (
    <div style={{ display: 'flex', flexDirection: isAdmin ? 'row' : 'row-reverse', gap: 10, marginBottom: 14, alignItems: 'flex-end' }}>
      <div style={{ width: 34, height: 34, borderRadius: '50%', background: isAdmin ? 'var(--gradient-primary)' : 'linear-gradient(135deg,#00E5A0,#00B5CC)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, flexShrink: 0 }}>
        {isAdmin ? '👨‍💼' : '👤'}
      </div>
      <div style={{ maxWidth: '75%' }}>
        <div style={{ fontSize: 10, color: 'var(--text-muted)', marginBottom: 4, textAlign: isAdmin ? 'left' : 'right' }}>
          {msg.sender_name} · {fmtDate(msg.created_at)}
        </div>
        <div style={{
          background: isAdmin ? 'rgba(108,99,255,0.12)' : 'rgba(0,229,160,0.1)',
          border: `1px solid ${isAdmin ? 'rgba(108,99,255,0.25)' : 'rgba(0,229,160,0.25)'}`,
          borderRadius: isAdmin ? '4px 14px 14px 14px' : '14px 4px 14px 14px',
          padding: '10px 14px', fontSize: 13, color: 'var(--text-primary)', lineHeight: 1.6,
        }}>
          {msg.message}
        </div>
      </div>
    </div>
  );
}

// ══ Main Page ════════════════════════════════════════════════════════════════════
export default function HelpSupport() {
  const { user } = useAuthStore();
  const [tickets, setTickets] = useState([]);
  const [activeTicket, setActiveTicket] = useState(null); // full ticket with messages
  const [view, setView] = useState('home'); // 'home' | 'tickets' | 'new' | 'thread'
  const [loading, setLoading] = useState(false);
  const [replyText, setReplyText] = useState('');
  const msgEndRef = useRef(null);

  // New ticket form
  const [form, setForm] = useState({ subject: '', category: 'other', priority: 'medium', message: '' });

  // Poll for ticket updates every 15s when viewing a thread
  useEffect(() => {
    fetchMyTickets();
  }, []);

  useEffect(() => {
    if (view === 'thread' && activeTicket) {
      const interval = setInterval(() => refreshThread(activeTicket.id), 15000);
      return () => clearInterval(interval);
    }
  }, [view, activeTicket]);

  useEffect(() => {
    // Auto scroll to bottom of conversation
    msgEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [activeTicket?.messages]);

  const fetchMyTickets = async () => {
    try {
      const res = await supportAPI.getMyTickets();
      setTickets(res.data.data || []);
    } catch { /* silent */ }
  };

  const openThread = async (ticketId) => {
    setLoading(true);
    try {
      const res = await supportAPI.getTicketDetail(ticketId);
      setActiveTicket(res.data.data);
      setView('thread');
    } catch { toast.error('Failed to load ticket'); }
    finally { setLoading(false); }
  };

  const refreshThread = async (ticketId) => {
    try {
      const res = await supportAPI.getTicketDetail(ticketId);
      setActiveTicket(res.data.data);
    } catch { /* silent */ }
  };

  const handleCreateTicket = async (e) => {
    e.preventDefault();
    if (!form.subject || !form.message) return toast.error('Fill all required fields');
    setLoading(true);
    try {
      const res = await supportAPI.createTicket(form);
      toast.success(`Ticket ${res.data.data.ticket_number} created!`);
      setForm({ subject: '', category: 'other', priority: 'medium', message: '' });
      await fetchMyTickets();
      setView('tickets');
    } catch (err) { toast.error(err.response?.data?.message || 'Failed to create ticket'); }
    finally { setLoading(false); }
  };

  const handleReply = async () => {
    if (!replyText.trim()) return;
    setLoading(true);
    try {
      await supportAPI.addMessage(activeTicket.id, { message: replyText });
      setReplyText('');
      await refreshThread(activeTicket.id);
      await fetchMyTickets();
      toast.success('Reply sent!');
    } catch (err) { toast.error(err.response?.data?.message || 'Failed to send reply'); }
    finally { setLoading(false); }
  };

  const handleCloseTicket = async () => {
    if (!window.confirm('Close this ticket?')) return;
    try {
      await supportAPI.closeTicket(activeTicket.id);
      toast.success('Ticket closed');
      await fetchMyTickets();
      await refreshThread(activeTicket.id);
    } catch { toast.error('Failed to close ticket'); }
  };

  const openTicketCount = tickets.filter(t => t.status === 'open' || t.status === 'in_progress').length;

  // ── Styles ────────────────────────────────────────────────────────────────────
  const cardS = { background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 16, padding: 24, transition: 'all 0.25s' };
  const inputS = { width: '100%', background: 'var(--bg-input)', border: '1px solid var(--border)', borderRadius: 10, padding: '11px 14px', color: 'var(--text-primary)', fontFamily: 'Outfit, sans-serif', fontSize: 14, outline: 'none', boxSizing: 'border-box' };
  const btnPrimary = { background: 'var(--gradient-primary)', color: 'white', border: 'none', borderRadius: 10, padding: '12px 22px', fontWeight: 700, fontSize: 14, cursor: 'pointer', fontFamily: 'Outfit, sans-serif', transition: 'all 0.2s' };
  const btnSecondary = { background: 'transparent', color: 'var(--text-secondary)', border: '1px solid var(--border)', borderRadius: 10, padding: '10px 18px', fontWeight: 600, fontSize: 13, cursor: 'pointer', fontFamily: 'Outfit, sans-serif', transition: 'all 0.2s' };

